/**
 * The architecture map's words against its code: every folder the map draws
 * has a line in tools/archmap-notes.ts, and no line there names a folder or a
 * workspace that is gone.
 *
 *   npx vitest run site/tests/archmap.ts
 *
 * The map itself (docs/engine/architecture-map.md) is generated by
 * tools/archmap.mts when the docs are built, so it can never be stale; its
 * descriptions are written by hand, and this is what keeps them from going
 * stale instead.
 */
import { test, expect } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { buildModel } from "../../tools/archmap.mjs";
import { COMPONENTS, CONTAINERS } from "../../tools/archmap-notes";

const ROOT = fileURLToPath(new URL("../..", import.meta.url));
const model = buildModel(ROOT);

test("every folder the map draws is described", () => {
  const missing = Object.keys(model.components).filter((c) => !COMPONENTS[c]);
  expect(missing, "add a line for each to COMPONENTS in tools/archmap-notes.ts").toEqual([]);
});

test("no description names a folder that is gone", () => {
  const gone = Object.keys(COMPONENTS).filter((c) => !model.components[c]);
  expect(gone, "remove these from COMPONENTS in tools/archmap-notes.ts").toEqual([]);
});

test("every workspace is a container of the map, and every container a folder here", () => {
  for (const c of Object.keys(CONTAINERS)) expect(existsSync(`${ROOT}/${c}`), `${c}/ in CONTAINERS`).toBe(true);
  const { workspaces } = JSON.parse(readFileSync(`${ROOT}/package.json`, "utf8")) as { workspaces: string[] };
  expect(new Set([...workspaces, "tools"])).toEqual(new Set(Object.keys(CONTAINERS)));
});

test("an import resolves to a file the map knows", () => {
  for (const [p, f] of Object.entries(model.files)) for (const i of f.i) expect(model.files[i], `${p} imports ${i}`).toBeDefined();
});
